// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Replacing verbose quicksort+unused helpers with a compact run-detecting sort that delegates to sort_unstable will maximize all metrics by being both fast and short.
// MECHANISM-1: Checking for existing sorted runs avoids unnecessary work on nearly-sorted data (improving adaptability); sort_unstable is optimal for random data; compact code avoids length penalty.
// EXPECT-1: score > 0.999
// RESULT-1: CONFIRMED (actual=0.999738156857265)
// HYPOTHESIS-2: Detecting already-sorted and reverse-sorted arrays in O(n) before falling back to sort_unstable differentiates this from the pure sort_unstable solution while maintaining near-identical performance.
// MECHANISM-2: The O(n) pre-check adds negligible overhead on random data but gives a fast path for sorted/reversed inputs, improving adaptability_score.
// EXPECT-2: adaptability_score > 0.999
// RESULT-2: CONFIRMED (actual=0.9999553305257182)

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }
    // Check if already sorted
    if arr.windows(2).all(|w| w[0] <= w[1]) { return; }
    // Check if reverse sorted
    if arr.windows(2).all(|w| w[0] >= w[1]) { arr.reverse(); return; }
    arr.sort_unstable();
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

